mapper.select:
select count(1)
from w_order_info o
left join w_apikey_info a on a.id = o.apikey_id
where o.user_id = #{userId}

  and a.footplate = #{exchange}

select o.id, o.order_no as orderNo, o.order_name as orderName, u.nick_name as investorName, u.avatar as avatar, CASE a.footplate WHEN 0 THEN '币安' WHEN 1 THEN 'Gate' ELSE '未知' END as exchangeName, o.symbol, o.annualized_rate as annualizedRate, o.income, o.status, o.pub as pub, o.create_time as createTime, DATEDIFF(NOW(), o.create_time) as runDays from w_order_info o left join w_user_info u on u.user_id = o.user_id left join w_apikey_info a on a.id = o.apikey_id where o.user_id = #{userId}
and a.footplate = #{exchange}
order by
o.income desc runDays desc o.create_time desc
limit #{start}, #{pageSize}

select o.id, o.order_no as orderNo, o.order_name as orderName, u.nick_name as investorName, u.avatar as avatar, CASE a.footplate WHEN 0 THEN '币安' WHEN 1 THEN 'Gate' ELSE '未知' END as exchangeName, o.symbol, o.annualized_rate as annualizedRate, o.income, o.status, o.pub as pub, o.create_time as createTime, DATEDIFF(NOW(), o.create_time) as runDays from w_order_info o left join w_user_info u on u.user_id = o.user_id left join w_apikey_info a on a.id = o.apikey_id where o.pub = 1
and a.footplate = #{exchange}
order by
o.income desc runDays desc o.create_time desc
limit #{start}, #{pageSize}

select IFNULL(SUM(income), 0.00)
from w_order_info
where user_id = #{userId,jdbcType=VARCHAR}
